✅ Cách 3: toSignal() — Kết hợp RxJS + Signals
import { toSignal } from &#039;@angular/core/rxjs-interop&#039;;

@Component({
  template: `
    @for (case of cases(); track case.id) {
      &lt;app-case-card [case]=&quot;case&quot; /&gt;
    }
  `
})
export class CaseListComponent {
