Bài tiếp theo: 17. HTTP Interceptors &amp; Auth Patterns 🔐

Angular-Latest-Series/17-HTTP-Intercepto.content:
17. HTTP Interceptors &amp; Auth Patterns 🔐

Tại sao quan trọng với enterprise?
Mọi dự án ngân hàng đều cần: tự động gắn JWT token, xử lý token hết hạn, retry khi lỗi 401, log request/response. Interceptor là lớp middleware của Angular HTTP — viết một lần, áp dụng cho toàn bộ API call.


🧱 1. Interceptor là gì?
Ẩn dụ: Trạm kiểm soát hải quan
Hãy tưởng tượng mọi request HTTP là một container hàng hoá xuất khẩu, và mọi response là hàng nhập khẩu:
graph LR
    App[Ứng dụng Angular]

    subgraph Interceptor Chain
        I1[Auth Interceptor&lt;br/&gt;Gắn JWT token]
        I2[Logging Interceptor&lt;br/&gt;Ghi log request]
        I3[Error Interceptor&lt;br/&gt;Xử lý lỗi tập trung]
    end

    API[Backend API]

    App --&gt; I1 --&gt; I2 --&gt; I3 --&gt; API
    API --&gt; I3 --&gt; I2 --&gt; I1 --&gt; App


🔑 2. Auth Interceptor: Tự động gắn JWT
Pattern đầy đủ cho enterprise
// auth.interceptor.ts
import { HttpInterceptorFn, HttpRequest, HttpHandlerFn } from &#039;@angular/common/http&#039;;
import { inject } from &#039;@angular/core&#039;;
import { catchError, switchMap, throwError, BehaviorSubject, filter, take } from &#039;rxjs&#039;;

let isRefreshing = false;
const refreshTokenSubject = new BehaviorSubject&lt;string | null&gt;(null);

export const authInterceptor: HttpInterceptorFn = (req, next) =&gt; {
  const authService = inject(AuthService);
  const token = authService.getAccessToken();

  // Không gắn token cho các request public (login, refresh)
  if (isPublicUrl(req.url)) {
    return next(req);
  }

  // Gắn token vào header
  const authReq = addAuthHeader(req, token);

  return next(authReq).pipe(
    catchError(error =&gt; {
      if (error.status === 401 &amp;&amp; !req.url.includes(&#039;refresh-token&#039;)) {
        return handleTokenRefresh(req, next, authService);
      }
      return throwError(() =&gt; error);
    })
  );
};

// Thêm Bearer token
function addAuthHeader(req: HttpRequest&lt;unknown&gt;, token: string | null) {
  if (!token) return req;
  return req.clone({
    setHeaders: { Authorization: `Bearer ${token}` }
  });
}

// Tự động refresh token khi hết hạn (401)
function handleTokenRefresh(
  req: HttpRequest&lt;unknown&gt;,
  next: HttpHandlerFn,
  authService: AuthService
) {
  if (!isRefreshing) {
    isRefreshing = true;
    refreshTokenSubject.next(null);

    return authService.refreshToken().pipe(
      switchMap(({ accessToken }) =&gt; {
        isRefreshing = false;
        refreshTokenSubject.next(accessToken);
        return next(addAuthHeader(req, accessToken));
      }),
      catchError(err =&gt; {
        isRefreshing = false;
        authService.logout(); // Đăng xuất nếu refresh thất bại
        return throwError(() =&gt; err);
      })
    );
  }

  // Có request khác đang đợi token mới → queue lại
  return refreshTokenSubject.pipe(
    filter(token =&gt; token !== null),
    take(1),
    switchMap(token =&gt; next(addAuthHeader(req, token!)))
  );
}

function isPublicUrl(url: string): boolean {
  const publicUrls = [&#039;/auth/login&#039;, &#039;/auth/refresh&#039;, &#039;/public/&#039;];
  return publicUrls.some(u =&gt; url.includes(u));
}

📝 3. Logging Interceptor: Ghi log request/response
// logging.interceptor.ts
export const loggingInterceptor: HttpInterceptorFn = (req, next) =&gt; {
  const startTime = Date.now();
  const logger = inject(LoggerService);

  logger.debug(`[HTTP] → ${req.method} ${req.url}`, {
    body: req.body,
    params: req.params.toString()
  });

  return next(req).pipe(
    tap({
      next: (event) =&gt; {
        if (event instanceof HttpResponse) {
          const duration = Date.now() - startTime;
          logger.debug(`[HTTP] ← ${event.status} ${req.url} (${duration}ms)`);

          // Cảnh báo nếu response chậm quá 3 giây
          if (duration &gt; 3000) {
            logger.warn(`[SLOW API] ${req.url} took ${duration}ms`);
          }
        }
      },
      error: (error) =&gt; {
        logger.error(`[HTTP] ← ERROR ${error.status} ${req.url}`, error);
      }
    })
  );
};

❌ 4. Error Interceptor: Xử lý lỗi tập trung
// error.interceptor.ts
import { HttpInterceptorFn, HttpErrorResponse } from &#039;@angular/common/http&#039;;
import { inject } from &#039;@angular/core&#039;;
import { catchError, throwError } from &#039;rxjs&#039;;

export const errorInterceptor: HttpInterceptorFn = (req, next) =&gt; {
  const toastService = inject(ToastService);
  const router = inject(Router);

  return next(req).pipe(
    catchError((error: HttpErrorResponse) =&gt; {
      switch (error.status) {
        case 400:
          // Lỗi validation từ server — hiển thị message cụ thể
          const message = error.error || &#039;Dữ liệu không hợp lệ&#039;;
          toastService.error(message);
          break;

        case 401:
          // Không xác thực — đã xử lý ở authInterceptor
          break;

        case 403:
          toastService.warning(&#039;Bạn không có quyền thực hiện thao tác này&#039;);
          router.navigate([&#039;/forbidden&#039;]);
          break;

        case 404:
          toastService.error(&#039;Không tìm thấy dữ liệu&#039;);
          break;

        case 422:
          // Validation errors từ backend (Laravel/Spring Boot format)
          const validationErrors = error.error
          if (validationErrors) {
            const firstError = Object.values(validationErrors)[0] as string[];
            toastService.error(firstError[0]);
          }
          break;

        case 500:
        case 502:
        case 503:
          toastService.error(&#039;Hệ thống đang gặp sự cố. Vui lòng thử lại sau.&#039;);
          break;

        default:
          if (!navigator.onLine) {
            toastService.error(&#039;Mất kết nối mạng!&#039;);
          }
      }

      // Luôn propagate lỗi để component tự xử lý thêm nếu cần
      return throwError(() =&gt; error);
    })
  );
};

🔄 5. Retry Interceptor: Tự động thử lại
// retry.interceptor.ts
import { retry, timer } from &#039;rxjs&#039;;

export const retryInterceptor: HttpInterceptorFn = (req, next) =&gt; {
  // Chỉ retry GET request, không retry POST/PUT (tránh duplicate)
  if (req.method !== &#039;GET&#039;) {
    return next(req);
  }

  return next(req).pipe(
    retry({
      count: 3, // Thử lại tối đa 3 lần
      delay: (error, retryCount) =&gt; {
        // Chỉ retry 5xx errors, không retry 4xx
        if (error.status &gt;= 400 &amp;&amp; error.status &lt; 500) {
          throw error;
        }
        // Exponential backoff: 1s, 2s, 4s
        return timer(1000 * Math.pow(2, retryCount - 1));
      }
    })
  );
};

⚙️ 6. Đăng ký Interceptors
// app.config.ts
import { provideHttpClient, withInterceptors } from &#039;@angular/common/http&#039;;

export const appConfig: ApplicationConfig = {
  providers: [
    provideHttpClient(
      withInterceptors([
        // Thứ tự quan trọng! Interceptor đầu tiên bọc ngoài cùng
        loggingInterceptor,    // 1. Log trước tiên
        authInterceptor,       // 2. Gắn auth token
        retryInterceptor,      // 3. Retry nếu cần
        errorInterceptor,      // 4. Xử lý lỗi cuối cùng
      ])
    ),
    // ...
  ]
};

🔐 7. AuthService: Quản lý token
// auth.service.ts
@Injectable({ providedIn: &#039;root&#039; })
export class AuthService {
  private http = inject(HttpClient);
  private router = inject(Router);

  private readonly ACCESS_TOKEN_KEY = &#039;pdms_access_token&#039;;
  private readonly REFRESH_TOKEN_KEY = &#039;pdms_refresh_token&#039;;

  // Signal cho trạng thái đăng nhập
  private _isLoggedIn = signal(this.hasValidToken());
  isLoggedIn = this._isLoggedIn.asReadonly();

  login(credentials: LoginDto): Observable&lt;AuthResponse&gt; {
    return this.http.post&lt;AuthResponse&gt;(&#039;/api/auth/login&#039;, credentials).pipe(
      tap(res =&gt; this.saveTokens(res))
    );
  }

  refreshToken(): Observable&lt;{ accessToken: string }&gt; {
    const refreshToken = this.getRefreshToken();
    return this.http.post&lt;{ accessToken: string }&gt;(&#039;/api/auth/refresh&#039;, { refreshToken });
  }

  logout() {
    localStorage.removeItem(this.ACCESS_TOKEN_KEY);
    localStorage.removeItem(this.REFRESH_TOKEN_KEY);
    this._isLoggedIn.set(false);
    this.router.navigate([&#039;/login&#039;]);
  }

  getAccessToken(): string | null {
    return localStorage.getItem(this.ACCESS_TOKEN_KEY);
  }

  private getRefreshToken(): string | null {
    return localStorage.getItem(this.REFRESH_TOKEN_KEY);
  }

  private saveTokens(res: AuthResponse) {
    localStorage.setItem(this.ACCESS_TOKEN_KEY, res.accessToken);
    localStorage.setItem(this.REFRESH_TOKEN_KEY, res.refreshToken);
    this._isLoggedIn.set(true);
  }

  private hasValidToken(): boolean {
    const token = this.getAccessToken();
    if (!token) return false;
    // Decode JWT và kiểm tra exp (đơn giản)
    try {
      const payload = JSON.parse(atob(token.split(&#039;.&#039;)[1]));
      return payload.exp * 1000 &gt; Date.now();
    } catch {
      return false;
    }
  }
}

📊 8. Tóm tắt luồng Auth hoàn chỉnh
sequenceDiagram
    participant User
    participant Angular
    participant AuthInterceptor
    participant API

    User-&gt;&gt;Angular: Thao tác cần API
    Angular-&gt;&gt;AuthInterceptor: HTTP Request
    AuthInterceptor-&gt;&gt;AuthInterceptor: Đọc Access Token

    alt Token còn hạn
        AuthInterceptor-&gt;&gt;API: Request + Bearer Token
        API--&gt;&gt;Angular: 200 OK + Data
    else Token hết hạn (401)
        AuthInterceptor-&gt;&gt;API: POST /auth/refresh
        API--&gt;&gt;AuthInterceptor: New Access Token
        AuthInterceptor-&gt;&gt;API: Retry Request + New Token
        API--&gt;&gt;Angular: 200 OK + Data
    else Refresh cũng hết hạn
        AuthInterceptor-&gt;&gt;Angular: logout() + redirect /login
    end


Bài tiếp theo: 18. Route Guards &amp; Resolvers: Kiểm soát điều hướng 🛡️

Angular-Latest-Series/18-Route-Guards-an.content:
18. Route Guards &amp; Resolvers: Kiểm soát điều hướng 🛡️

Tại sao quan trọng?
Guards là “bảo vệ” đứng trước cánh cửa mỗi route. Resolvers là “người chuẩn bị” tải dữ liệu trước khi component render. Cả hai giúp ứng dụng banking an toàn và trải nghiệm mượt mà hơn.


🚪 1. Route Guards là gì?
Ẩn dụ: Hệ thống bảo mật toà nhà ngân hàng
graph LR
    User[Người dùng&lt;br/&gt;muốn vào phòng] --&gt; Receptionist[canActivate&lt;br/&gt;Kiểm tra thẻ từ]
    Receptionist -- Có quyền --&gt; Inside[canActivateChild&lt;br/&gt;Kiểm tra từng phòng con]
    Receptionist -- Không quyền --&gt; Login[Redirect đến&lt;br/&gt;Trang đăng nhập]

    InsideRoom[Đang ở trong phòng&lt;br/&gt;muốn rời đi] --&gt; Exit[canDeactivate&lt;br/&gt;Xác nhận thoát?&lt;br/&gt;Form chưa lưu?]

    LoadData[Trước khi vào phòng] --&gt; Resolver[resolve&lt;br/&gt;Chuẩn bị dữ liệu&lt;br/&gt;như setup phòng họp]


🔐 2. canActivate Guard: Kiểm tra đăng nhập
// auth.guard.ts
import { inject } from &#039;@angular/core&#039;;
import { CanActivateFn, Router } from &#039;@angular/router&#039;;

export const authGuard: CanActivateFn = (route, state) =&gt; {
  const authService = inject(AuthService);
  const router = inject(Router);

  if (authService.isLoggedIn()) {
    return true;
  }

  // Lưu URL người dùng muốn vào để sau khi login redirect về
  router.navigate([&#039;/login&#039;], { 
    queryParams: { returnUrl: state.url } 
  });
  return false;
};

👮 3. Role/Permission Guard: Kiểm tra quyền hạn
// permission.guard.ts
import { inject } from &#039;@angular/core&#039;;
import { CanActivateFn, ActivatedRouteSnapshot } from &#039;@angular/router&#039;;

export const permissionGuard: CanActivateFn = (route: ActivatedRouteSnapshot) =&gt; {
  const permissionService = inject(PermissionService);
  const router = inject(Router);

  // Lấy danh sách quyền yêu cầu từ route data
  const requiredPermissions: string[] = route.data[&#039;permissions&#039;] ?? [];
  const requiredRoles: string[] = route.data[&#039;roles&#039;] ?? [];

  const hasPermission = requiredPermissions.length === 0 || 
    requiredPermissions.every(p =&gt; permissionService.hasPermission(p));

  const hasRole = requiredRoles.length === 0 || 
    requiredRoles.some(r =&gt; permissionService.hasRole(r));

  if (hasPermission &amp;&amp; hasRole) {
    return true;
  }

  router.navigate([&#039;/forbidden&#039;]);
  return false;
};

// Dùng trong routes:
// {
//   path: &#039;approve-credit&#039;,
//   component: ApproveCreditComponent,
//   data: { 
//     permissions: [&#039;CREDIT_APPROVE&#039;],
//     roles: [&#039;APPROVER&#039;, &#039;MANAGER&#039;]
//   },
//   canActivate: [authGuard, permissionGuard]
// }

⚠️ 4. canDeactivate Guard: Cảnh báo khi rời trang chưa lưu
// unsaved-changes.guard.ts
import { CanDeactivateFn } from &#039;@angular/router&#039;;
import { Observable } from &#039;rxjs&#039;;

// Interface để component implement
export interface CanComponentDeactivate {
  canDeactivate(): boolean | Observable&lt;boolean&gt; | Promise&lt;boolean&gt;;
}

export const unsavedChangesGuard: CanDeactivateFn&lt;CanComponentDeactivate&gt; = (component) =&gt; {
  return component.canDeactivate ? component.canDeactivate() : true;
};

// Trong component form:
@Component({ ... })
export class CreditApplicationFormComponent implements CanComponentDeactivate {
  private isDirty = signal(false);
  private dialogService = inject(DialogService);

  canDeactivate(): Observable&lt;boolean&gt; {
    if (!this.isDirty()) {
      return of(true); // Không có thay đổi, thoát bình thường
    }

    // Hiện dialog xác nhận
    return this.dialogService.confirm({
      title: &#039;Bỏ các thay đổi?&#039;,
      message: &#039;Form chưa được lưu. Bạn có chắc muốn rời trang này không?&#039;,
      confirmText: &#039;Rời trang&#039;,
      cancelText: &#039;Tiếp tục chỉnh sửa&#039;
    });
  }
}

📦 5. Resolver: Tải dữ liệu trước khi render
Ẩn dụ: Phục vụ phòng chuẩn bị trước khi khách vào
Thay vì component render trước rồi mới tải dữ liệu (màn hình trắng/spinner), Resolver tải dữ liệu trước rồi mới cho vào.
// case-file-detail.resolver.ts
import { inject } from &#039;@angular/core&#039;;
import { ResolveFn, ActivatedRouteSnapshot, Router } from &#039;@angular/router&#039;;
import { catchError, EMPTY } from &#039;rxjs&#039;;

export const caseFileDetailResolver: ResolveFn&lt;CaseFile&gt; = (
  route: ActivatedRouteSnapshot
) =&gt; {
  const caseFileService = inject(CaseFileService);
  const router = inject(Router);
  const id = route.paramMap.get(&#039;id&#039;)!;

  return caseFileService.getById(id).pipe(
    catchError(() =&gt; {
      // Nếu không tìm thấy, redirect về danh sách
      router.navigate([&#039;/case-files&#039;]);
      return EMPTY; // EMPTY = không emit gì, route sẽ không activate
    })
  );
};

🗺️ 6. Cấu hình Routes đầy đủ cho enterprise
// app.routes.ts
import { Routes } from &#039;@angular/router&#039;;

export const routes: Routes = [
  // Public routes — không cần guard
  {
    path: &#039;login&#039;,
    loadComponent: () =&gt; import(&#039;./features/auth/login/login.component&#039;)
      .then(m =&gt; m.LoginComponent)
  },

  // Protected routes — cần đăng nhập
  {
    path: &#039;&#039;,
    canActivate: [authGuard],
    loadComponent: () =&gt; import(&#039;./layouts/main-layout/main-layout.component&#039;)
      .then(m =&gt; m.MainLayoutComponent),
    children: [
      {
        path: &#039;dashboard&#039;,
        loadComponent: () =&gt; import(&#039;./features/dashboard/dashboard.component&#039;)
          .then(m =&gt; m.DashboardComponent)
      },

      // Lazy-loaded feature module với guard phân quyền
      {
        path: &#039;case-files&#039;,
        canActivate: [permissionGuard],
        data: { permissions: [&#039;CASE_FILE_VIEW&#039;] },
        children: [
          {
            path: &#039;&#039;,
            loadComponent: () =&gt; import(&#039;./features/case-file/list/case-file-list.component&#039;)
              .then(m =&gt; m.CaseFileListComponent)
          },
          {
            path: &#039;:id&#039;,
            resolve: { caseFile: caseFileDetailResolver }, // ← Resolver
            loadComponent: () =&gt; import(&#039;./features/case-file/detail/case-file-detail.component&#039;)
              .then(m =&gt; m.CaseFileDetailComponent)
          },
          {
            path: &#039;:id/edit&#039;,
            canActivate: [permissionGuard],
            canDeactivate: [unsavedChangesGuard], // ← Cảnh báo rời trang
            data: { permissions: [&#039;CASE_FILE_EDIT&#039;] },
            resolve: { caseFile: caseFileDetailResolver },
            loadComponent: () =&gt; import(&#039;./features/case-file/edit/case-file-edit.component&#039;)
              .then(m =&gt; m.CaseFileEditComponent)
          }
        ]
      },

      // Approve — chỉ APPROVER và MANAGER mới vào được
      {
        path: &#039;approvals&#039;,
        canActivate: [permissionGuard],
        data: { roles: [&#039;APPROVER&#039;, &#039;MANAGER&#039;] },
        loadChildren: () =&gt; import(&#039;./features/approval/approval.routes&#039;)
          .then(m =&gt; m.approvalRoutes)
      }
    ]
  },

  // Fallback
  { path: &#039;forbidden&#039;, loadComponent: () =&gt; import(&#039;./pages/forbidden.component&#039;).then(m =&gt; m.ForbiddenComponent) },
  { path: &#039;**&#039;, redirectTo: &#039;dashboard&#039; }
];

🔄 7. Dùng dữ liệu từ Resolver trong Component
// case-file-detail.component.ts
@Component({
  standalone: true,
  template: `
    &lt;h1&gt;{{ caseFile.borrowerName }}&lt;/h1&gt;
    &lt;p&gt;Mã hồ sơ: {{ caseFile.id }}&lt;/p&gt;
    &lt;p&gt;Số tiền vay: {{ caseFile.loanAmount | currency:&#039;VND&#039; }}&lt;/p&gt;
    &lt;app-status-badge [status]=&quot;caseFile.status&quot; /&gt;
  `
})
export class CaseFileDetailComponent {
  private route = inject(ActivatedRoute);

  // Lấy dữ liệu đã được resolve — không cần loading state!
  caseFile: CaseFile = this.route.snapshot.data[&#039;caseFile&#039;];
}

📊 8. So sánh: Không có vs Có Resolver
sequenceDiagram
    participant User
    participant Router
    participant Component
    participant API

    rect rgb(255, 200, 200)
        Note over User,API: Không có Resolver (Xấu)
        User-&gt;&gt;Router: Navigate /case-files/123
        Router-&gt;&gt;Component: Render ngay (màn hình trống)
        Component-&gt;&gt;API: fetchData(123)
        API--&gt;&gt;Component: Data (sau 300ms)
        Component-&gt;&gt;User: Hiển thị data (loader khó chịu)
    end

    rect rgb(200, 255, 200)
        Note over User,API: Có Resolver (Tốt)
        User-&gt;&gt;Router: Navigate /case-files/123
        Router-&gt;&gt;API: fetchData(123) qua Resolver
        API--&gt;&gt;Router: Data (sau 300ms)
        Router-&gt;&gt;Component: Render với data sẵn sàng
        Component-&gt;&gt;User: Hiển thị ngay, không loader
    end


Bài tiếp theo: 19. Content Projection &amp; Advanced Template Patterns 🎭

Angular-Latest-Series/19-Content-Project.content:
19. Content Projection &amp; Advanced Template Patterns 🎭

Tại sao cần học?
Content Projection là cách xây dựng các component tái sử dụng linh hoạt — modal, card, table, layout — mà không bị ràng buộc vào nội dung cụ thể. Đây là kỹ năng thiết yếu để xây dựng Design System cho dự án enterprise.


📦 1. Content Projection: Hộp thư có slot
Ẩn dụ: Khuôn bánh có ô trống
Hãy tưởng tượng bạn có một khuôn làm bánh đặc biệt với các ô trống có thể điền:

Ô tiêu đề → điền gì tuỳ ý
Ô nội dung → điền gì tuỳ ý
Ô footer → điền gì tuỳ ý

Đó chính là Content Projection với &lt;ng-content&gt;.

🕳️ 2. Single Slot Projection (ng-content cơ bản)
// card.component.ts
@Component({
  selector: &#039;app-card&#039;,
  standalone: true,
  template: `
    &lt;div class=&quot;card&quot;&gt;
      &lt;div class=&quot;card-body&quot;&gt;
        &lt;ng-content&gt;&lt;/ng-content&gt;  &lt;!-- ← Ô trống, điền gì vào đây tuỳ ý --&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `
})
export class CardComponent {}
&lt;!-- Cách dùng --&gt;
&lt;app-card&gt;
  &lt;h2&gt;Thông tin hồ sơ vay&lt;/h2&gt;
  &lt;p&gt;CIF: 0123456789&lt;/p&gt;
&lt;/app-card&gt;

&lt;!-- Kết quả render --&gt;
&lt;div class=&quot;card&quot;&gt;
  &lt;div class=&quot;card-body&quot;&gt;
    &lt;h2&gt;Thông tin hồ sơ vay&lt;/h2&gt;
    &lt;p&gt;CIF: 0123456789&lt;/p&gt;
  &lt;/div&gt;
&lt;/div&gt;

🎯 3. Multi-Slot Projection (select attribute)
// dialog.component.ts
@Component({
  selector: &#039;app-dialog&#039;,
  standalone: true,
  template: `
    &lt;div class=&quot;dialog-overlay&quot;&gt;
      &lt;div class=&quot;dialog-container&quot;&gt;
        &lt;!-- Header slot --&gt;
        &lt;div class=&quot;dialog-header&quot;&gt;
          &lt;ng-content select=&quot;[dialog-title]&quot;&gt;&lt;/ng-content&gt;
        &lt;/div&gt;

        &lt;!-- Body slot --&gt;
        &lt;div class=&quot;dialog-body&quot;&gt;
          &lt;ng-content select=&quot;[dialog-body]&quot;&gt;&lt;/ng-content&gt;
        &lt;/div&gt;

        &lt;!-- Footer slot --&gt;
        &lt;div class=&quot;dialog-footer&quot;&gt;
          &lt;ng-content select=&quot;[dialog-footer]&quot;&gt;&lt;/ng-content&gt;
          &lt;!-- Fallback nếu không truyền footer --&gt;
          &lt;ng-content&gt;&lt;/ng-content&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `
})
export class DialogComponent {
  @Input() isOpen = false;
}
&lt;!-- Cách dùng: Rõ ràng, linh hoạt --&gt;
&lt;app-dialog [isOpen]=&quot;showApprovalDialog&quot;&gt;
  &lt;h2 dialog-title&gt;Xác nhận phê duyệt hồ sơ&lt;/h2&gt;

  &lt;div dialog-body&gt;
    &lt;p&gt;Bạn có chắc muốn phê duyệt hồ sơ &lt;strong&gt;{{ caseFile.id }}&lt;/strong&gt;?&lt;/p&gt;
    &lt;app-loan-summary [data]=&quot;caseFile&quot; /&gt;
  &lt;/div&gt;

  &lt;div dialog-footer&gt;
    &lt;button (click)=&quot;cancel()&quot;&gt;Huỷ&lt;/button&gt;
    &lt;button class=&quot;primary&quot; (click)=&quot;confirm()&quot;&gt;Phê duyệt&lt;/button&gt;
  &lt;/div&gt;
&lt;/app-dialog&gt;

👁️ 4. ViewChild &amp; ContentChild
ViewChild: Truy cập element trong template
@Component({
  standalone: true,
  template: `
    &lt;input #searchInput type=&quot;text&quot; placeholder=&quot;Tìm kiếm hồ sơ...&quot; /&gt;
    &lt;app-data-table #dataTable [data]=&quot;tableData&quot; /&gt;
  `
})
export class CaseFileSearchComponent implements AfterViewInit {
  // Truy cập DOM element
  @ViewChild(&#039;searchInput&#039;) searchInput!: ElementRef&lt;HTMLInputElement&gt;;

  // Truy cập component con
  @ViewChild(&#039;dataTable&#039;) dataTable!: DataTableComponent;

  // Với signal (Angular 17+) — khuyến khích dùng
  searchInputRef = viewChild&lt;ElementRef&gt;(&#039;searchInput&#039;);
  dataTableRef = viewChild(DataTableComponent);

  ngAfterViewInit() {
    // Focus vào ô tìm kiếm khi component load
    this.searchInput.nativeElement.focus();
  }

  exportData() {
    // Gọi method của component con
    this.dataTable.exportToExcel();
  }
}
ContentChild: Truy cập element được project vào
// expandable-section.component.ts
@Component({
  selector: &#039;app-expandable&#039;,
  standalone: true,
  template: `
    &lt;div class=&quot;header&quot; (click)=&quot;toggle()&quot;&gt;
      &lt;ng-content select=&quot;[expandable-header]&quot;&gt;&lt;/ng-content&gt;
      &lt;span&gt;{{ isExpanded ? &#039;▲&#039; : &#039;▼&#039; }}&lt;/span&gt;
    &lt;/div&gt;
    @if (isExpanded) {
      &lt;div class=&quot;content&quot;&gt;
        &lt;ng-content select=&quot;[expandable-content]&quot;&gt;&lt;/ng-content&gt;
      &lt;/div&gt;
    }
  `
})
export class ExpandableSectionComponent {
  // Truy cập content được truyền từ bên ngoài
  @ContentChild(&#039;customTrigger&#039;) customTrigger?: ElementRef;

  isExpanded = signal(false);

  toggle() {
    this.isExpanded.update(v =&gt; !v);
  }
}

🏗️ 5. Pattern thực chiến: Generic Table Component
// data-table.component.ts
interface TableColumn&lt;T&gt; {
  key: keyof T;
  label: string;
  sortable?: boolean;
  formatter?: (value: any) =&gt; string;
}

@Component({
  selector: &#039;app-data-table&#039;,
  standalone: true,
  imports: [CommonModule],
  template: `
    &lt;table&gt;
      &lt;thead&gt;
        &lt;tr&gt;
          @for (col of columns; track col.key) {
            &lt;th (click)=&quot;col.sortable &amp;&amp; sortBy(col.key)&quot;&gt;
              {{ col.label }}
              @if (col.sortable) { &lt;span&gt;⇅&lt;/span&gt; }
            &lt;/th&gt;
          }
          &lt;!-- Slot cho action columns --&gt;
          &lt;ng-content select=&quot;[table-header-extra]&quot;&gt;&lt;/ng-content&gt;
        &lt;/tr&gt;
      &lt;/thead&gt;
      &lt;tbody&gt;
        @for (row of data; track row[trackByKey]) {
          &lt;tr&gt;
            @for (col of columns; track col.key) {
              &lt;td&gt;
                {{ col.formatter ? col.formatter(row[col.key]) : row[col.key] }}
              &lt;/td&gt;
            }
            &lt;!-- Slot cho action cells (nút Edit, Delete, ...) --&gt;
            &lt;ng-content select=&quot;[table-row-action]&quot;&gt;&lt;/ng-content&gt;
          &lt;/tr&gt;
        }
      &lt;/tbody&gt;
    &lt;/table&gt;

    &lt;!-- Slot cho pagination --&gt;
    &lt;ng-content select=&quot;[table-footer]&quot;&gt;&lt;/ng-content&gt;
  `
})
export class DataTableComponent&lt;T extends Record&lt;string, any&gt;&gt; {
  @Input({ required: true }) data: T[] = [];
  @Input({ required: true }) columns: TableColumn&lt;T&gt;[] = [];
  @Input() trackByKey: keyof T = &#039;id&#039; as keyof T;

  @Output() sortChange = new EventEmitter&lt;{ key: keyof T; direction: &#039;asc&#039; | &#039;desc&#039; }&gt;();

  sortState = signal&lt;{ key: keyof T | null; dir: &#039;asc&#039; | &#039;desc&#039; }&gt;({ key: null, dir: &#039;asc&#039; });

  sortBy(key: keyof T) {
    const current = this.sortState();
    const newDir = current.key === key &amp;&amp; current.dir === &#039;asc&#039; ? &#039;desc&#039; : &#039;asc&#039;;
    this.sortState.set({ key, dir: newDir });
    this.sortChange.emit({ key, direction: newDir });
  }
}
&lt;!-- Sử dụng generic table cho danh sách hồ sơ --&gt;
&lt;app-data-table [data]=&quot;caseFiles&quot; [columns]=&quot;caseFileColumns&quot;&gt;
  &lt;!-- Thêm cột action tùy ý --&gt;
  &lt;ng-template table-row-action let-row&gt;
    &lt;td&gt;
      &lt;button (click)=&quot;viewDetail(row.id)&quot;&gt;Chi tiết&lt;/button&gt;
      @if (canApprove) {
        &lt;button (click)=&quot;approve(row.id)&quot;&gt;Phê duyệt&lt;/button&gt;
      }
    &lt;/td&gt;
  &lt;/ng-template&gt;

  &lt;app-pagination [total]=&quot;totalCount&quot; table-footer (pageChange)=&quot;onPageChange($event)&quot; /&gt;
&lt;/app-data-table&gt;

🎨 6. ng-template &amp; ng-container
ng-template: Khuôn mẫu chưa render
@Component({
  template: `
    &lt;!-- ng-container: Không tạo DOM element thật, chỉ là grouping --&gt;
    &lt;ng-container *ngIf=&quot;isLoading; else contentTemplate&quot;&gt;
      &lt;app-skeleton /&gt;
    &lt;/ng-container&gt;

    &lt;!-- ng-template: Định nghĩa template có thể tái sử dụng --&gt;
    &lt;ng-template #contentTemplate&gt;
      &lt;div class=&quot;content&quot;&gt;...&lt;/div&gt;
    &lt;/ng-template&gt;

    &lt;!-- Dùng trong table: Không tạo &lt;div&gt; thừa trong &lt;tr&gt;&lt;td&gt; --&gt;
    &lt;tr&gt;
      &lt;ng-container *ngIf=&quot;showExtraColumns&quot;&gt;
        &lt;td&gt;Cột A&lt;/td&gt;
        &lt;td&gt;Cột B&lt;/td&gt;
      &lt;/ng-container&gt;
    &lt;/tr&gt;
  `
})
