Bài tiếp theo: 20. Lazy Loading &amp; Code Splitting: Tối ưu bundle size 🚀

Angular-Latest-Series/20-Lazy-Loading-an.content:
20. Lazy Loading &amp; Code Splitting: Tối ưu Bundle Size 🚀

Tại sao quan trọng với enterprise?
Dự án banking có hàng chục màn hình. Nếu load tất cả cùng lúc, lần đầu vào app người dùng phải chờ tải về 5-10MB JavaScript. Lazy Loading chia nhỏ bundle, chỉ tải khi cần → app khởi động nhanh hơn 50-80%.


📦 1. Bundle là gì? Vấn đề là gì?
Ẩn dụ: Siêu thị vs Cửa hàng tiện lợi
graph TD
    subgraph Không có Lazy Loading
        A[App khởi động] --&gt; B[Tải TOÀN BỘ code: 8MB]
        B --&gt; C[Người dùng chờ... 5 giây]
        C --&gt; D[Mở trang Login]
    end

    subgraph Có Lazy Loading
        E[App khởi động] --&gt; F[Chỉ tải core: 200KB]
        F --&gt; G[Mở trang Login ngay: 0.5 giây]
        G --&gt; H[Người dùng vào Dashboard]
        H --&gt; I[Tải Dashboard module: 300KB]
        I --&gt; J[Vào Case Files]
        J --&gt; K[Tải Case Files module: 400KB]
    end

    style C fill:#ffcccc
    style G fill:#ccffcc


⚙️ 2. Lazy Loading Routes
Cấu hình cơ bản
// app.routes.ts
export const routes: Routes = [
  // Tải ngay khi app khởi động (Critical path)
  {
    path: &#039;login&#039;,
    component: LoginComponent // ← Import trực tiếp = Eager loading
  },

  // Lazy load khi người dùng điều hướng đến
  {
    path: &#039;dashboard&#039;,
    loadComponent: () =&gt; 
      import(&#039;./features/dashboard/dashboard.component&#039;)
        .then(m =&gt; m.DashboardComponent)
  },

  // Lazy load cả một nhóm routes (feature module)
  {
    path: &#039;case-files&#039;,
    loadChildren: () =&gt; 
      import(&#039;./features/case-file/case-file.routes&#039;)
        .then(m =&gt; m.caseFileRoutes)
  },

  {
    path: &#039;approvals&#039;,
    loadChildren: () =&gt; 
      import(&#039;./features/approval/approval.routes&#039;)
        .then(m =&gt; m.approvalRoutes)
  },

  {
    path: &#039;reports&#039;,
    loadChildren: () =&gt; 
      import(&#039;./features/reports/reports.routes&#039;)
        .then(m =&gt; m.reportsRoutes)
  }
];
Feature routes file
// case-file.routes.ts
export const caseFileRoutes: Routes = [
  {
    path: &#039;&#039;,
    loadComponent: () =&gt; import(&#039;./list/case-file-list.component&#039;)
      .then(m =&gt; m.CaseFileListComponent)
  },
  {
    path: &#039;new&#039;,
    loadComponent: () =&gt; import(&#039;./create/case-file-create.component&#039;)
      .then(m =&gt; m.CaseFileCreateComponent)
  },
  {
    path: &#039;:id&#039;,
    loadComponent: () =&gt; import(&#039;./detail/case-file-detail.component&#039;)
      .then(m =&gt; m.CaseFileDetailComponent)
  }
];

⚡ 3. Preloading: Tải trước khi cần
Lazy Loading có nhược điểm: lần đầu vào route sẽ có một khoảng chờ nhỏ. Preloading giải quyết điều này:
// app.config.ts
import { provideRouter, withPreloading, PreloadAllModules } from &#039;@angular/router&#039;;

export const appConfig: ApplicationConfig = {
  providers: [
    // PreloadAllModules: Sau khi app load xong, tải ngầm tất cả lazy modules
    provideRouter(routes, withPreloading(PreloadAllModules))
  ]
};
Custom Preloading Strategy
Tải trước một số route quan trọng, bỏ qua những route ít dùng:
// selective-preload.strategy.ts
import { Injectable } from &#039;@angular/core&#039;;
import { PreloadingStrategy, Route } from &#039;@angular/router&#039;;
import { Observable, of } from &#039;rxjs&#039;;

@Injectable({ providedIn: &#039;root&#039; })
export class SelectivePreloadStrategy implements PreloadingStrategy {
  preload(route: Route, load: () =&gt; Observable&lt;any&gt;): Observable&lt;any&gt; {
    // Chỉ preload nếu route có flag preload: true
    if (route.data[&#039;preload&#039;]) {
      console.log(`Preloading: ${route.path}`);
      return load();
    }
    return of(null);
  }
}

// Trong routes:
{
  path: &#039;dashboard&#039;,
  data: { preload: true }, // ← Sẽ được preload
  loadChildren: () =&gt; import(&#039;./features/dashboard/dashboard.routes&#039;)
    .then(m =&gt; m.dashboardRoutes)
},
{
  path: &#039;reports&#039;, // Không có preload: true → Chỉ tải khi cần
  loadChildren: () =&gt; import(&#039;./features/reports/reports.routes&#039;)
    .then(m =&gt; m.reportsRoutes)
}

🎭 4. Lazy Loading với Suspense: ng-defer (Angular 17+)
@Component({
  template: `
    &lt;!-- Defer: Trì hoãn việc render component nặng --&gt;
    @defer (on viewport) {
      &lt;!-- Chỉ render khi user scroll đến vùng này --&gt;
      &lt;app-heavy-chart [data]=&quot;chartData&quot; /&gt;
    } @placeholder {
      &lt;!-- Hiện trong khi chờ --&gt;
      &lt;div class=&quot;chart-placeholder&quot;&gt;Đang tải biểu đồ...&lt;/div&gt;
    } @loading (minimum 500ms) {
      &lt;app-skeleton height=&quot;300px&quot; /&gt;
    } @error {
      &lt;p&gt;Không thể tải biểu đồ&lt;/p&gt;
    }

    &lt;!-- Defer khi idle (trình duyệt rảnh) --&gt;
    @defer (on idle) {
      &lt;app-notification-panel /&gt;
    }

    &lt;!-- Defer khi có interaction --&gt;
    @defer (on interaction(triggerBtn)) {
      &lt;app-advanced-filters /&gt;
    }
    &lt;button #triggerBtn&gt;Bộ lọc nâng cao&lt;/button&gt;
  `
})
export class DashboardComponent {
  chartData = input&lt;ChartData[]&gt;([]);
}

🖼️ 5. Lazy Loading Images (NgOptimizedImage)
import { NgOptimizedImage } from &#039;@angular/common&#039;;

@Component({
  standalone: true,
  imports: [NgOptimizedImage],
  template: `
    &lt;!-- LCP image: priority để load sớm --&gt;
    &lt;img ngSrc=&quot;/assets/hero-banner.webp&quot; width=&quot;1200&quot; height=&quot;400&quot; priority /&gt;

    &lt;!-- Non-critical images: lazy by default --&gt;
    &lt;img ngSrc=&quot;/assets/avatar-{{ user.id }}.jpg&quot; width=&quot;64&quot; height=&quot;64&quot; /&gt;

    &lt;!-- Với responsive sizes --&gt;
    &lt;img 
      ngSrc=&quot;/assets/document-preview.jpg&quot;
      [width]=&quot;400&quot; 
      [height]=&quot;300&quot;
      sizes=&quot;(max-width: 768px) 100vw, 400px&quot;
    /&gt;
  `
})
export class ProfileComponent {
  user = input.required&lt;User&gt;();
}

📊 6. Phân tích Bundle Size
# Build với stats
ng build --stats-json

# Xem bundle analysis (cài webpack-bundle-analyzer)
npx webpack-bundle-analyzer dist/pdms/stats.json
Kết quả trước và sau Lazy Loading
TRƯỚC (Eager):
main.js                          8.2 MB  ← Tải tất cả khi khởi động

SAU (Lazy):
main.js                          210 KB  ← Bundle chính (Core + Login)
chunk-dashboard.js               340 KB  ← Tải khi vào Dashboard
chunk-case-files.js              480 KB  ← Tải khi vào Case Files
chunk-approvals.js               290 KB  ← Tải khi vào Approvals
chunk-reports.js                 620 KB  ← Tải khi vào Reports


🔧 7. Best Practices tổng hợp
flowchart TD
    Q[Module/Component này có cần ngay không?] 
    Q -- Có: Login, Core Layout --&gt; Eager[Eager Loading&lt;br/&gt;Import trực tiếp]
    Q -- Không: Feature pages --&gt; Lazy[Lazy Loading&lt;br/&gt;loadChildren / loadComponent]

    Lazy --&gt; Usage{Người dùng dùng thường xuyên?}
    Usage -- Thường xuyên: Dashboard, CaseFile --&gt; Preload[Thêm preload: true&lt;br/&gt;Hoặc PreloadAllModules]
    Usage -- Ít khi: Reports, Admin --&gt; NoPreload[Không preload&lt;br/&gt;Tải khi cần]

    style Eager fill:#fff9c4
    style Lazy fill:#c8e6c9
    style Preload fill:#c8e6c9

Checklist Lazy Loading cho dự án enterprise:

✅ Mỗi feature module là một lazy route
✅ Shared/Core modules là eager (nhỏ, cần thiết)
✅ Bật preloading cho các route thường dùng
✅ Dùng @defer cho components nặng trong trang (biểu đồ, PDF viewer)
✅ Dùng NgOptimizedImage cho tất cả ảnh
✅ Định kỳ chạy bundle analyzer để phát hiện bloat


Bài tiếp theo: 21. Error Handling &amp; Global Patterns: Xử lý lỗi như người lớn 🛡️

Angular-Latest-Series/21-Error-Handling-.content:
21. Error Handling &amp; Global Patterns: Xử lý lỗi như người lớn 🛡️

Tại sao quan trọng?
Ứng dụng banking không được phép “chết lặng” — mọi lỗi phải được xử lý, log, và thông báo rõ ràng. Bài này xây dựng một hệ thống error handling đa tầng, từ component đến global.


🏛️ 1. Kiến trúc Error Handling 3 tầng
graph TD
    Error[Lỗi xảy ra] --&gt; L1{Tầng 1: HTTP Interceptor}
    L1 -- Lỗi HTTP --&gt; HttpHandler[Xử lý theo status code&lt;br/&gt;401/403/404/500...]
    L1 -- Lỗi khác --&gt; L2{Tầng 2: Component Error}

    HttpHandler --&gt; Toast[Toast notification]
    HttpHandler --&gt; L2

    L2 -- Xử lý được --&gt; ComponentUI[Hiện error state trong UI]
    L2 -- Không xử lý --&gt; L3{Tầng 3: Global Error Handler}

    L3 --&gt; ErrorPage[Trang lỗi tổng]
    L3 --&gt; Sentry[Ghi log lên Sentry/Server]

    style L1 fill:#fff9c4
    style L2 fill:#c8e6c9
    style L3 fill:#ffccbc


🌐 2. Global Error Handler
// global-error.handler.ts
import { ErrorHandler, Injectable, inject, NgZone } from &#039;@angular/core&#039;;
import { Router } from &#039;@angular/router&#039;;

@Injectable()
export class GlobalErrorHandler implements ErrorHandler {
  private router = inject(Router);
  private logger = inject(LoggerService);
  private ngZone = inject(NgZone);

  handleError(error: unknown): void {
    // Phân loại lỗi
    if (error instanceof HttpErrorResponse) {
      // Đã xử lý ở interceptor
      return;
    }

    if (error instanceof TypeError) {
      this.logger.error(&#039;TypeError:&#039;, error.message, error.stack);
    } else if (error instanceof Error) {
      this.logger.error(&#039;Runtime Error:&#039;, error.message, error.stack);
    } else {
      this.logger.error(&#039;Unknown Error:&#039;, error);
    }

    // Gửi lên error tracking service (Sentry, Datadog, etc.)
    this.reportToErrorTracking(error);

    // Redirect đến trang lỗi (phải dùng ngZone vì có thể ở ngoài zone)
    this.ngZone.run(() =&gt; {
      this.router.navigate([&#039;/error&#039;], {
        queryParams: { 
          message: error instanceof Error ? error.message : &#039;Lỗi không xác định&#039;
        }
      });
    });
  }

  private reportToErrorTracking(error: unknown) {
    // Tích hợp Sentry
    // Sentry.captureException(error);

    // Hoặc gửi về internal logging API
    // this.http.post(&#039;/api/error-logs&#039;, { error: String(error), url: location.href });
  }
}

// Đăng ký trong app.config.ts
export const appConfig: ApplicationConfig = {
  providers: [
    { provide: ErrorHandler, useClass: GlobalErrorHandler },
    // ...
  ]
};

🎯 3. Error Boundary Pattern trong Angular
Angular không có Error Boundary như React, nhưng ta có thể mô phỏng:
// error-boundary.component.ts
@Component({
  selector: &#039;app-error-boundary&#039;,
  standalone: true,
  template: `
    @if (hasError()) {
      &lt;div class=&quot;error-boundary&quot;&gt;
        &lt;div class=&quot;error-icon&quot;&gt;⚠️&lt;/div&gt;
        &lt;h3&gt;{{ title() }}&lt;/h3&gt;
        &lt;p&gt;{{ message() }}&lt;/p&gt;
        @if (showRetry()) {
          &lt;button (click)=&quot;retry()&quot;&gt;Thử lại&lt;/button&gt;
        }
      &lt;/div&gt;
    } @else {
      &lt;ng-content&gt;&lt;/ng-content&gt;
    }
  `
})
export class ErrorBoundaryComponent {
  @Input() title = &#039;Đã có lỗi xảy ra&#039;;
  @Input() message = &#039;Vui lòng thử lại hoặc liên hệ hỗ trợ.&#039;;
  @Input() showRetry = true;

  hasError = signal(false);
  private retryFn?: () =&gt; void;

  catchError(error: Error, retryFn?: () =&gt; void) {
    this.hasError.set(true);
    this.retryFn = retryFn;
  }

  retry() {
    this.hasError.set(false);
    this.retryFn();
  }
}

📊 4. Component Error State Pattern
// Kiểu dữ liệu chuẩn cho async state
type AsyncState&lt;T&gt; = 
  | { status: &#039;idle&#039; }
  | { status: &#039;loading&#039; }
  | { status: &#039;success&#039;; data: T }
  | { status: &#039;error&#039;; error: string };

@Component({
  standalone: true,
  template: `
    @switch (state().status) {
      @case (&#039;idle&#039;) {
        &lt;p class=&quot;hint&quot;&gt;Chọn bộ lọc để xem dữ liệu&lt;/p&gt;
      }
      @case (&#039;loading&#039;) {
        &lt;app-skeleton-table [rows]=&quot;10&quot; /&gt;
      }
      @case (&#039;error&#039;) {
        &lt;app-error-card 
          [message]=&quot;state().error&quot;
          (retry)=&quot;loadData()&quot;
        /&gt;
      }
      @case (&#039;success&#039;) {
        &lt;app-transaction-table [data]=&quot;state().data&quot; /&gt;
      }
    }
  `
})
export class TransactionPageComponent {
  state = signal&lt;AsyncState&lt;Transaction[]&gt;&gt;({ status: &#039;idle&#039; });

  private txService = inject(TransactionService);

  loadData() {
    this.state.set({ status: &#039;loading&#039; });

    this.txService.getAll().subscribe({
      next: (data) =&gt; this.state.set({ status: &#039;success&#039;, data }),
      error: (err) =&gt; this.state.set({ 
        status: &#039;error&#039;, 
        error: err.error ?? &#039;Không tải được dữ liệu&#039; 
      })
    });
  }
}

🔔 5. Toast Notification Service
// toast.service.ts
export interface Toast {
  id: string;
  type: &#039;success&#039; | &#039;error&#039; | &#039;warning&#039; | &#039;info&#039;;
  title: string;
  message?: string;
  duration?: number; // ms, 0 = không tự tắt
}

@Injectable({ providedIn: &#039;root&#039; })
export class ToastService {
  private toasts = signal&lt;Toast[]&gt;([]);
  readonly toasts$ = this.toasts.asReadonly();

  success(title: string, message?: string) {
    this.show({ type: &#039;success&#039;, title, message, duration: 3000 });
  }

  error(title: string, message?: string) {
    // Lỗi không tự tắt — người dùng phải bấm đóng
    this.show({ type: &#039;error&#039;, title, message, duration: 0 });
  }

  warning(title: string, message?: string) {
    this.show({ type: &#039;warning&#039;, title, message, duration: 5000 });
  }

  private show(toast: Omit&lt;Toast, &#039;id&#039;&gt;) {
    const id = crypto.randomUUID();
    this.toasts.update(t =&gt; [...t, { ...toast, id }]);

    if (toast.duration &amp;&amp; toast.duration &gt; 0) {
      setTimeout(() =&gt; this.dismiss(id), toast.duration);
    }
  }

  dismiss(id: string) {
    this.toasts.update(t =&gt; t.filter(toast =&gt; toast.id !== id));
  }
}
// toast-container.component.ts (đặt trong app.component.html)
@Component({
  selector: &#039;app-toast-container&#039;,
  standalone: true,
  template: `
    &lt;div class=&quot;toast-container&quot;&gt;
      @for (toast of toastService.toasts$(); track toast.id) {
        &lt;div class=&quot;toast toast--{{ toast.type }}&quot; [@slideIn]&gt;
          &lt;span class=&quot;toast-icon&quot;&gt;
            @switch (toast.type) {
              @case (&#039;success&#039;) { ✅ }
              @case (&#039;error&#039;) { ❌ }
              @case (&#039;warning&#039;) { ⚠️ }
              @case (&#039;info&#039;) { ℹ️ }
            }
          &lt;/span&gt;
          &lt;div class=&quot;toast-content&quot;&gt;
            &lt;strong&gt;{{ toast.title }}&lt;/strong&gt;
            @if (toast.message) { &lt;p&gt;{{ toast.message }}&lt;/p&gt; }
          &lt;/div&gt;
          &lt;button class=&quot;toast-close&quot; (click)=&quot;toastService.dismiss(toast.id)&quot;&gt;✕&lt;/button&gt;
        &lt;/div&gt;
      }
    &lt;/div&gt;
  `
})
export class ToastContainerComponent {
  toastService = inject(ToastService);
}

📋 6. Form Validation Error Pattern
// validation-message.component.ts — Tái sử dụng cho mọi form
@Component({
  selector: &#039;app-validation-message&#039;,
  standalone: true,
  template: `
    @if (control &amp;&amp; control.invalid &amp;&amp; (control.dirty || control.touched)) {
      &lt;div class=&quot;validation-errors&quot;&gt;
        @if (control.errors[&#039;required&#039;]) {
          &lt;span class=&quot;error&quot;&gt;Trường này không được để trống&lt;/span&gt;
        }
        @if (control.errors[&#039;minlength&#039;]) {
          &lt;span class=&quot;error&quot;&gt;
            Tối thiểu {{ control.errors[&#039;minlength&#039;].requiredLength }} ký tự
          &lt;/span&gt;
        }
        @if (control.errors[&#039;maxlength&#039;]) {
          &lt;span class=&quot;error&quot;&gt;
            Tối đa {{ control.errors[&#039;maxlength&#039;].requiredLength }} ký tự
          &lt;/span&gt;
        }
        @if (control.errors[&#039;pattern&#039;]) {
          &lt;span class=&quot;error&quot;&gt;{{ label }} không đúng định dạng&lt;/span&gt;
        }
        @if (control.errors[&#039;serverError&#039;]) {
          &lt;span class=&quot;error&quot;&gt;{{ control.errors[&#039;serverError&#039;] }}&lt;/span&gt;
        }
      &lt;/div&gt;
    }
  `
})
export class ValidationMessageComponent {
  @Input() control: AbstractControl | null = null;
  @Input() label = &#039;Giá trị&#039;;
}

