func TestCreditEventSerializeDeserialize(t *testing.T) {
    f := fory.NewFory(true)
    require.NoError(t, f.RegisterTagType(&quot;CreditEvent&quot;, domain.CreditEvent{}))

    original := domain.CreditEvent{
