func TestNilFieldHandling(t *testing.T) {
    f := fory.NewFory(true)
    require.NoError(t, f.RegisterTagType(&quot;CreditEvent&quot;, domain.CreditEvent{}))

    event := domain.CreditEvent{EventId: 1} // minimal fields

    bytes, err := f.Marshal(&amp;event)
