    }
}

// ❌ Nguyên nhân 3: Gọi write op trong @PostConstruct hoặc @Scheduled
// mà không có @Transactional
@PostConstruct
public void init() {
    repo.save(new Config(...));  // Chưa chắc có transaction context
}
Fix từng nguyên nhân:
