        Ok(br#&quot;[{&quot;id&quot;:&quot;1&quot;,&quot;value&quot;:&quot;alpha&quot;}]&quot;#.to_vec())
    }
    fn parse(&amp;self, raw: &amp;[u8]) -&gt; Result&lt;Vec&lt;Record&gt;, String&gt; {
