// internal/delivery/http/document_handler.go
package http

import (
    &quot;encoding/json&quot;
    &quot;net/http&quot;
    &quot;github.com/go-chi/chi/v5&quot;
    &quot;github.com/bach/pdms/internal/domain&quot;
