🔧 Programmatic Transaction (UserTransaction)
@ApplicationScoped
public class BatchService {

    @Inject
    UserTransaction tx;  // Programmatic control

    public void processBatch(List&lt;Long&gt; ids) throws Exception {
        tx.begin();
        try {
            for (Long id : ids) {
                processItem(id);
            }
            tx.commit();
        } catch (Exception e) {
            tx.rollback();
            throw e;
        }
    }
}

