@Path(&quot;/{id}&quot;)
public Uni&lt;Response&gt; getUser(@PathParam(&quot;id&quot;) Long id) {
    return userService.findById(id)
        .onItem().transform(user -&gt; Response.ok(user).build())
        .onFailure(NotFoundException.class)
            .recoverWithItem(Response.status(404).build());
}

