template.send(&quot;doc-events&quot;, event);

// Producer: Micronaut — declarative!
@KafkaClient
public interface DocEventProducer {
    @Topic(&quot;doc-events&quot;)
    void send(@KafkaKey String key, DocEvent event);
}

