    access_type     VARCHAR(50) DEFAULT &#039;FULL&#039;,
    is_active       BOOLEAN DEFAULT true,
    _event_id       UUID,                   -- idempotency key
    _synced_at      TIMESTAMP DEFAULT NOW(),
    UNIQUE (user_sub, dept_id)
