  rabbitmq:
    # Timeout kết nối
    connection-timeout: 10000

  # Retry khi startup (dùng @Retryable hoặc Spring Retry)
  listener:
    simple:
      missing-queues-fatal: false  # ⬅️ Không crash nếu queue chưa có

