  return (
    &lt;tr onMouseEnter={prefetchCase}&gt;
      &lt;td&gt;&lt;Link to={`/cases/${caseItem.id}`}&gt;{caseItem.caseCode}&lt;/Link&gt;&lt;/td&gt;
    &lt;/tr&gt;
  );
}

