8. Release Profile Checklist
[profile.release]
opt-level = 3        # Max optimization
lto = &quot;thin&quot;         # Link-time optimization — inlining cross-crate
codegen-units = 1    # Compiler thấy toàn bộ code → inline tốt hơn
