9. Common Anti-patterns
// ❌ Clone thay vì borrow
fn print(name: String) { println!(&quot;{}&quot;, name); }
// ✅ Borrow
fn print(name: &amp;str) { println!(&quot;{}&quot;, name); }

// ❌ Collect trung gian rồi iterate lại
let v: Vec&lt;_&gt; = items.iter().map(f).collect();
for x in &amp;v { use(x); }
// ✅ Không collect trung gian
items.iter().map(f).for_each(|x| use(&amp;x));

// ❌ Vec::contains trong loop — O(n²)
for item in &amp;items {
    if known.contains(item) { ... }
}
// ✅ HashSet — O(1)
let set: HashSet&lt;_&gt; = known.iter().collect();
for item in &amp;items {
    if set.contains(item) { ... }
}

// ❌ Vec không có capacity hint
let mut v = Vec::new();
for _ in 0..1000 { v.push(...); } // ~10 reallocations
// ✅ Pre-allocate
let mut v = Vec::with_capacity(1000);
for _ in 0..1000 { v.push(...); } // 1 allocation

10. Performance Cheat Sheet: Java vs Rust













































Tình huốngJavaRustObject creationAlways heap + GCStack khi biết sizeString passingNew String (heap)&amp;str borrow (zero cost)Generic dispatchType erasure + boxingMonomorphized = zero costInterface callVirtual (vtable)Static với impl TraitIterator/StreamVirtual + boxingInlined, fused, no allocError handlingException (stack unwind)Result = zero cost enumThread~1MB stackTokio task ~8KB

