use actix_web::{web, App, HttpServer, middleware};
use sqlx::postgres::PgPoolOptions;
use std::sync::Arc;
use tracing_actix_web::TracingLogger;

mod config;
mod errors;
mod middleware;
mod models;
mod routes;
mod state;

#[actix_web::main]
async fn main() -&gt; std::io::Result&lt;()&gt; {
    // Tracing setup
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive(&quot;actix_web=info&quot;.parse().unwrap())
        )
        .json()
        .init();

    // Load config
    let config = config::Config::from_env().expect(&quot;Config load failed&quot;);
    let port = config.port;

    // DB pool
    let pool = PgPoolOptions::new()
        .max_connections(config.db_pool_size)
        .acquire_timeout(std::time::Duration::from_secs(3))
        .connect(&amp;config.database_url)
        .await
        .expect(&quot;DB connect failed&quot;);

    // Run migrations
    sqlx::migrate!(&quot;./migrations&quot;)
        .run(&amp;pool)
        .await
        .expect(&quot;Migration failed&quot;);

    let state = web::Data::new(state::AppState {
        db: pool,
        config: Arc::new(config),
        http_client: reqwest::Client::new(),
    });

    tracing::info!(&quot;Starting server on 0.0.0.0:{}&quot;, port);

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .app_data(
                web::JsonConfig::default()
                    .limit(1024 * 1024)
                    .error_handler(errors::json_error_handler)
            )
            // Global middleware (áp dụng cho tất cả routes)
            .wrap(TracingLogger::default())
            .wrap(actix_web::middleware::Compress::default())
            .wrap(actix_web::middleware::NormalizePath::trim())
            // Public routes
            .route(&quot;/health&quot;, web::get().to(routes::health_check))
            // Protected API
            .service(
                web::scope(&quot;/api/v1&quot;)
                    .wrap(middleware::auth::JwtAuth)
                    .configure(routes::users::config)
                    .configure(routes::documents::config)
            )
    })
    .workers(num_cpus::get())
    .bind(format!(&quot;0.0.0.0:{}&quot;, port))?
    .run()
    .await
}

