use crate::schema::users;

// INSERT một record
pub async fn create_user(
    conn: &amp;mut AsyncPgConnection,
    new_user: NewUser,
) -&gt; Result&lt;User, diesel::result::Error&gt; {
    diesel::insert_into(users::table)
        .values(&amp;new_user)
        .returning(User::as_returning())
        .get_result(conn)
        .await
}

// INSERT nhiều records
