    conn: &amp;mut AsyncPgConnection,
    new_users: &amp;[NewUser],
) -&gt; Result&lt;Vec&lt;User&gt;, diesel::result::Error&gt; {
    diesel::insert_into(users::table)
        .values(new_users)
        .returning(User::as_returning())
        .get_results(conn)
        .await
