// INSERT ON CONFLICT DO NOTHING
pub async fn upsert_user(
    conn: &amp;mut AsyncPgConnection,
    new_user: &amp;NewUser,
) -&gt; Result&lt;Option&lt;User&gt;, diesel::result::Error&gt; {
    diesel::insert_into(users::table)
        .values(new_user)
        .on_conflict(users::email)
        .do_nothing()
        .returning(User::as_returning())
        .get_result(conn)
