1.3 Basic Operations
use deadpool_redis::Connection;
use redis::AsyncCommands;

// Wrapper để dễ dùng hơn
pub struct RedisClient {
    pool: RedisPool,
}

impl RedisClient {
    pub fn new(pool: RedisPool) -&gt; Self {
        Self { pool }
    }

    async fn conn(&amp;self) -&gt; Result&lt;Connection, AppError&gt; {
        self.pool
            .get()
            .await
            .map_err(|e| AppError::Redis(e.to_string()))
    }

    // SET key value [EX seconds]
    pub async fn set&lt;V: serde::Serialize&gt;(
        &amp;self,
        key: &amp;str,
        value: &amp;V,
        ttl_secs: Option&lt;u64&gt;,
    ) -&gt; Result&lt;(), AppError&gt; {
        let json = serde_json::to_string(value)
            .map_err(|e| AppError::Serialization(e.to_string()))?;

        let mut conn = self.conn().await?;

        match ttl_secs {
            Some(ttl) =&gt; conn
                .set_ex::&lt;_, _, ()&gt;(key, json, ttl)
                .await
                .map_err(|e| AppError::Redis(e.to_string())),
            None =&gt; conn
                .set::&lt;_, _, ()&gt;(key, json)
                .await
                .map_err(|e| AppError::Redis(e.to_string())),
        }
    }

    // GET key → Option&lt;T&gt;
    pub async fn get&lt;V: serde::de::DeserializeOwned&gt;(
        &amp;self,
        key: &amp;str,
    ) -&gt; Result&lt;Option&lt;V&gt;, AppError&gt; {
        let mut conn = self.conn().await?;

        let result: Option&lt;String&gt; = conn
            .get(key)
            .await
            .map_err(|e| AppError::Redis(e.to_string()))?;

        match result {
            Some(json) =&gt; {
                let value = serde_json::from_str(&amp;json)
                    .map_err(|e| AppError::Serialization(e.to_string()))?;
                Ok(Some(value))
            }
            None =&gt; Ok(None),
        }
    }

    // DEL key
    pub async fn del(&amp;self, key: &amp;str) -&gt; Result&lt;bool, AppError&gt; {
        let mut conn = self.conn().await?;
        let deleted: i64 = conn
            .del(key)
            .await
            .map_err(|e| AppError::Redis(e.to_string()))?;
        Ok(deleted &gt; 0)
    }

    // EXISTS key
    pub async fn exists(&amp;self, key: &amp;str) -&gt; Result&lt;bool, AppError&gt; {
        let mut conn = self.conn().await?;
        let exists: bool = conn
            .exists(key)
            .await
            .map_err(|e| AppError::Redis(e.to_string()))?;
        Ok(exists)
    }

    // EXPIRE key seconds
    pub async fn expire(&amp;self, key: &amp;str, ttl_secs: u64) -&gt; Result&lt;(), AppError&gt; {
        let mut conn = self.conn().await?;
        conn.expire::&lt;_, ()&gt;(key, ttl_secs as i64)
            .await
            .map_err(|e| AppError::Redis(e.to_string()))
    }

    // TTL key
    pub async fn ttl(&amp;self, key: &amp;str) -&gt; Result&lt;i64, AppError&gt; {
        let mut conn = self.conn().await?;
        conn.ttl(key)
            .await
            .map_err(|e| AppError::Redis(e.to_string()))
    }
}

