            .incr(&quot;counter&quot;, 1)
            .query_async(&amp;mut conn)
            .await
            .map_err(|e| AppError::Redis(e.to_string()))?;

    println!(&quot;get_result: {:?}, counter: {}&quot;, get_result, incr_result);
    Ok(())
}
