3.3 use_resource — Reactive Async
use dioxus::prelude::*;

// use_resource: re-run khi dependencies (signal) thay đổi
// Tương đương useQuery trong TanStack Query (React)
#[component]
fn SearchPage() -&gt; Element {
    let mut query = use_signal(|| String::new());

    // Re-fetch tự động khi query signal thay đổi
    let results = use_resource(move || async move {
        let q = query.read().clone();
        if q.is_empty() {
            return Ok(vec![]);
        }
        // Debounce nhỏ
        tokio::time::sleep(std::time::Duration::from_millis(300)).await;

        reqwest::get(format!(&quot;api.example.com/search{q}&quot;))
            .await?
            .json::&lt;Vec&lt;String&gt;&gt;()
            .await
    });

    rsx! {
        div {
            input {
                r#type: &quot;text&quot;,
                placeholder: &quot;Tìm kiếm...&quot;,
                oninput: move |e| query.set(e.value()),
            }
            match &amp;*results.read_unchecked() {
                Some(Ok(items)) =&gt; rsx! {
                    ul {
                        for item in items {
                            li { key: &quot;{item}&quot;, &quot;{item}&quot; }
                        }
                    }
                },
                Some(Err(e)) =&gt; rsx! { p { class: &quot;error&quot;, &quot;{e}&quot; } },
                None =&gt; rsx! { p { &quot;Đang tìm...&quot; } },
            }
        }
    }
}

