    let handle_refresh = move |_| async move {
        refreshing.set(true);
        // Simulate refresh
        tokio::time::sleep(std::time::Duration::from_millis(1000)).await;
        refreshing.set(false);
    };

    rsx! {
        div { class: &quot;screen documents-screen&quot;,
            // Pull-to-refresh indicator
