    view! {
        &lt;Suspense fallback=|| view! { &lt;div&gt;&quot;Loading...&quot;&lt;/div&gt; }&gt;
            {move || user.get().map(|u| match u {
                Ok(Some(u)) if u.role == &quot;ADMIN&quot; =&gt; view.run(),
