#[component]
fn PartiesStep(
    state: ReadSignal&lt;ContractWizardState&gt;,
    set_state: WriteSignal&lt;ContractWizardState&gt;,
) -&gt; impl IntoView {
    let add_party = move |_| {
        set_state.update(|s| s.parties.push(Party::default()));
    };

    let remove_party = move |idx: usize| {
