            &lt;For
                each=move || state.get().parties.into_iter().enumerate().collect::&lt;Vec&lt;_&gt;&gt;()
                key=|(idx, _)| *idx
                children=move |(idx, party)| {
                    let remove = move |_| remove_party(idx);
                    view! {
