sqlx::query!(
    &quot;INSERT INTO users (id, name, email)
     SELECT * FROM UNNEST($1::bigint[], $2::text[], $3::text[])&quot;,
    &amp;ids[..], &amp;names[..], &amp;emails[..]
)
.execute(&amp;pool)
.await?;
