                &lt;AppRoutes /&gt;
              &lt;/RouterProvider&gt;
            &lt;/LoanWorkflowProvider&gt;
          &lt;/NotificationProvider&gt;
        &lt;/ThemeProvider&gt;
      &lt;/AuthProvider&gt;
    &lt;/ErrorBoundary&gt;
  );
