    &lt;nav&gt;
      {/* Global loading indicator khi navigate */}
      &lt;Show when={isRouting()}&gt;
        &lt;div class=&quot;nav-progress-bar&quot; /&gt;
      &lt;/Show&gt;

      &lt;a href=&quot;/loans&quot; class={isLoansActive() ? &#039;active&#039; : &#039;&#039;}&gt;
        Khoản vay
      &lt;/a&gt;
      &lt;a href=&quot;/credit&quot; class={isCreditActive() ? &#039;active&#039; : &#039;&#039;}&gt;
        Hồ sơ tín dụng
      &lt;/a&gt;
    &lt;/nav&gt;
