          &lt;input
            type=&quot;text&quot;
            value={form.values.applicantName}
            onInput={e =&gt; form.field(&#039;applicantName&#039;).onChange(e.currentTarget.value)}
            onBlur={form.field(&#039;applicantName&#039;).onBlur}
            class={form.errors.applicantName ? &#039;input-error&#039; : &#039;&#039;}
