import { defineConfig } from &quot;@solidjs/start/config&quot;;

export default defineConfig({
  server: {
    preset: &quot;node-server&quot;, // hoặc &quot;vercel&quot;, &quot;cloudflare&quot;, &quot;bun&quot;
