        schema: creditApplicationSchema,
        initialValues: {
          applicantName: &#039;&#039;,
          requestedAmount: 0,
          tenor: 12,
          // ...
        },
        onSubmit: vi.fn(),
      });

      expect(form.values.applicantName).toBe(&#039;&#039;);
      expect(form.values.tenor).toBe(12);
      expect(form.isDirty()).toBe(false);
      dispose();
    });
  });

  it(&#039;validate field khi blur&#039;, () =&gt; {
